
function invoiceCustomer(i){return i.kind==='spare-parts'?(i.buyer||{name:'Walk-in customer',phone:'',address:''}):customer(state.jobs.find(j=>j.id===i.job));}
function partsBillLine(){return `<div class="parts-sale-line"><label class="checkbox-line"><input type="checkbox" name="outsourced">Outsourced</label><select name="salePart" aria-label="Inventory part"><option value="">Manual item (no stock change)</option>${state.inventory.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${p.stock} ${esc(p.unit||'')}</option>`).join('')}</select>${billLine()}</div>`;}
function partsBillForm(){
 if(!session?.admin||role!=='employer')return;
 openModal('Create spare-parts bill',`<form id="parts-bill-form"><div class="form-grid">${selectField('Use existing customer (optional)','saleCustomer',[['','Enter customer details'],...state.customers.map(c=>[c.id,c.name+' · '+c.phone])],'')}${field('Document date','date',today,'date',true)}${field('Customer name','buyerName','','text',true)}${field('Phone / WhatsApp','buyerPhone','','tel')}<div class="form-group full"><label for="parts-buyer-address">Customer address</label><textarea name="buyerAddress" id="parts-buyer-address" rows="2" maxlength="500"></textarea></div></div><div class="section-label">Description & quantity & unit price</div><div id="bill-lines">${partsBillLine()}</div>${btn('Add line item','add-parts-line','plus','small')}<div class="form-grid" style="margin-top:18px">${field('Discount (₹)','discount',0,'number',true,false,'min="0" step=".01"')}${field('Tax (%)','tax',0,'number',true,false,'min="0" max="100" step=".01"')}${selectField('Payment status','payment',[['Unpaid','Unpaid'],['Paid','Paid']],'Unpaid',true)}</div><label class="checkbox-line" style="margin-top:18px"><input name="reduceStock" type="checkbox" checked>Reduce stock for selected inventory parts when saving</label><p class="notice-inline">Outsourced and manual items do not change stock. Stock is deducted once when the bill is saved. Deleting a bill does not return stock; record returned items in Inventory.</p><div class="billing-total" id="bill-total"></div><p id="parts-bill-error" class="error" role="alert"></p></form>`,`<button class="btn light" type="reset" form="parts-bill-form">Clear</button>${btn('Cancel','close')}<button class="btn primary" type="submit" form="parts-bill-form">${icon('check')}Save bill</button>`,true,'Print directly or save as PDF from the browser print dialog.');
 updateBillTotal();
}
function preparePartsBill(data,lines,reduceStock){
 if(!String(data.buyerName||'').trim())throw new Error('Enter the customer name.');
 if(!/^\d{4}-\d{2}-\d{2}$/.test(data.date||''))throw new Error('Choose a valid bill date.');
 if(!['Paid','Unpaid'].includes(data.payment))throw new Error('Choose a payment status.');
 const discount=Number(data.discount),tax=Number(data.tax);
 if(!Number.isFinite(discount)||discount<0||!Number.isFinite(tax)||tax<0||tax>100)throw new Error('Enter a valid discount and tax percentage.');
 if(!lines.length||lines.length>20||lines.some(l=>!l.name.trim()||l.name.length>200||!Number.isFinite(l.qty)||l.qty<=0||l.qty>1000000||!Number.isFinite(l.price)||l.price<0||l.price>10000000))throw new Error('Add up to 20 items with a description, positive quantity and valid price.');
 const subtotal=lines.reduce((s,l)=>s+l.qty*l.price,0);if(discount>subtotal)throw new Error('Discount cannot exceed the subtotal.');
 const deductions=new Map();for(const line of lines){if(line.outsourced||!line.part)continue;const part=state.inventory.find(p=>p.id===line.part);if(!part)throw new Error('A selected part no longer exists. Select it again.');if(reduceStock)deductions.set(part.id,(deductions.get(part.id)||0)+line.qty);}
 const stock=[];for(const [id,qty] of deductions){const part=state.inventory.find(p=>p.id===id);if(qty>Number(part.stock)+.000001)throw new Error(`${part.name}: only ${part.stock} available. Reduce the quantity or update inventory.`);stock.push({id,stock:Math.round((part.stock-qty)*10000)/10000});}
 const id='SP-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase();
 return {stock,bill:{id,type:'Invoice',kind:'spare-parts',job:'',date:data.date,status:data.payment,...(data.payment==='Paid'?{paidDate:data.date}:{}),buyer:{name:String(data.buyerName).trim().slice(0,150),phone:String(data.buyerPhone||'').trim().slice(0,30),address:String(data.buyerAddress||'').trim().slice(0,500)},lines:lines.map(l=>({name:l.name.trim(),qty:l.qty,price:l.price,part:l.outsourced?'':(l.part||''),outsourced:!!l.outsourced})),discount,tax,stockDeducted:reduceStock}};
}
function partsBillDocument(i){return billDocument(i);}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='new-parts-bill')partsBillForm();if(b.dataset.action==='add-parts-line'){if(document.querySelectorAll('.parts-sale-line').length>=20)return toast('Use up to 20 items per bill.');document.getElementById('bill-lines').insertAdjacentHTML('beforeend',partsBillLine());updateBillTotal();}if(b.dataset.action==='remove-line'){const group=b.closest('.parts-sale-line');if(group){e.stopImmediatePropagation();if(document.querySelectorAll('.parts-sale-line').length>1)group.remove();else toast('Keep at least one item.');updateBillTotal();}}});
document.addEventListener('change',e=>{if(!e.target.closest('#parts-bill-form'))return;if(e.target.name==='outsourced'){const row=e.target.closest('.parts-sale-line'),select=row.querySelector('[name=salePart]');select.disabled=e.target.checked;select.hidden=e.target.checked;if(e.target.checked){select.value='';row.querySelector('[name=lineName]').value='';row.querySelector('[name=linePrice]').value=0;}updateBillTotal();}if(e.target.name==='salePart'){const p=state.inventory.find(p=>p.id===e.target.value),line=e.target.closest('.parts-sale-line');line.querySelector('[name=lineName]').value=p?.name||'';line.querySelector('[name=linePrice]').value=p?.price||0;updateBillTotal();}if(e.target.name==='saleCustomer'){const c=state.customers.find(c=>c.id===e.target.value),f=e.target.form;f.elements.buyerName.value=c?.name||'';f.elements.buyerPhone.value=c?.phone||'';f.elements.buyerAddress.value=c?.address||'';}});
document.addEventListener('reset',e=>{if(e.target.id==='parts-bill-form')setTimeout(()=>{e.target.querySelector('#bill-lines').innerHTML=partsBillLine();e.target.querySelector('#parts-bill-error').textContent='';updateBillTotal();},0);});
document.addEventListener('submit',async e=>{
 if(e.target.id!=='parts-bill-form')return;e.preventDefault();if(!session?.admin||role!=='employer')return;
 if(typeof wd!=='undefined'&&wd.saving)return;
 const f=e.target,error=f.querySelector('#parts-bill-error');
 try{const data=Object.fromEntries(new FormData(f)),lines=[...f.querySelectorAll('.parts-sale-line')].map(row=>({outsourced:row.querySelector('[name=outsourced]').checked,part:row.querySelector('[name=salePart]').value,name:row.querySelector('[name=lineName]').value.trim(),qty:Number(row.querySelector('[name=lineQty]').value),price:Number(row.querySelector('[name=linePrice]').value)}));const result=preparePartsBill(data,lines,f.elements.reduceStock.checked);
 for(const change of result.stock)state.inventory.find(p=>p.id===change.id).stock=change.stock;state.invoices.push(result.bill);closeModal();page='Invoices & estimates';query='';
 if(typeof saveRemote==='function'){renderLocal();rememberPage();await saveRemote();if(!state.invoices.some(i=>i.id===result.bill.id))return;}else render();
 invoicePreview(result.bill.id);
 }catch(x){if(f.isConnected)error.textContent=x.message;else toast(x.message);}
});

document.addEventListener('input',e=>{if(e.target.closest('#parts-bill-form')&&['lineQty','linePrice','discount','tax'].includes(e.target.name))updateBillTotal();});
